websocket_defense.secure_nodejs_implementation:
const WebSocket = require('ws');
const wss = new WebSocket.Server({ noServer: true });

const allowedOrigins = ['https://victim.com'];
const MESSAGE_RATE_LIMIT = 100; // per minute
const MAX_MESSAGE_SIZE = 1024 * 1024; // 1MB

server.on('upgrade', (request, socket, head) => {
  // 1. Origin validation
  const origin = request.headers.origin;
  if (!allowedOrigins.includes(origin)) {
    socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
    socket.destroy();
    return;
  }

  // 2. Authentication
  const token = new URL(request.url, 'ws://localhost').searchParams.get('token');
  if (!isValidToken(token)) {
    socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
    socket.destroy();
    return;
  }

  wss.handleUpgrade(request, socket, head, (ws) => {
    wss.emit('connection', ws, request, token);
  });
});

wss.on('connection', (ws, request, token) => {
  const userId = getUserIdFromToken(token);
  let messageCount = 0;
  let lastMinute = Date.now();

  ws.on('message', (message) => {
    // 3. Rate limiting
    if (Date.now() - lastMinute > 60000) {
      messageCount = 0;
      lastMinute = Date.now();
    }
    if (++messageCount > MESSAGE_RATE_LIMIT) {
      ws.close(1008, 'Rate limit exceeded');
      return;
    }

    // 4. Message size limit
    if (message.length > MAX_MESSAGE_SIZE) {
      ws.close(1009, 'Message too large');
      return;
    }

    // 5. Input validation
    let data;
    try {
      data = JSON.parse(message);
    } catch (e) {
      ws.send(JSON.stringify({error: 'Invalid message format'}));
      return;
    }

    // 6. Sanitize input
    const sanitizedMessage = sanitizeHtml(data.message);

    // 7. Authorization check
    if (data.action === 'admin' && !isAdmin(userId)) {
      ws.send(JSON.stringify({error: 'Unauthorized'}));
      return;
    }

    // Process message...
  });

  // 8. Connection timeout
  const pingInterval = setInterval(() => {
    if (ws.readyState === WebSocket.OPEN) {
      ws.ping();
    }
  }, 30000);

  ws.on('close', () => {
    clearInterval(pingInterval);
  });
});
